import React, { useEffect, useState } from 'react';
import { CFeeType, Descriptions, Divider, Space } from '@cloud-materials/common';
import dayjs from 'dayjs';
import type { ChargeStatusMap, TimeType } from '../interface';

export default () => {
  const date = [
    dayjs().add(7, 'd').add(20, 'h').valueOf(),
    dayjs().add(4, 'd').add(20, 'h').valueOf(),
    dayjs().add(7, 'h').add(20, 'm').add(50, 's').valueOf(),
    dayjs().add(7, 'm').add(50, 's').valueOf(),
    dayjs().add(20, 's').valueOf(),
    dayjs().subtract(3, 'd').valueOf(),
  ];

  const customStatusMap: ChargeStatusMap = {
    overdue: { statusName: '过期', nextStatusName: '回收', displayType: 'error' },
    owing: { statusName: '欠费', nextStatusName: '释放', displayType: 'error' },
    cancel: { statusName: '注销', nextStatusName: '释放', displayType: 'normal' },
  };
  // 此处设置时间仅用于展示关停时间失效后的效果
  const [closedTime, setClosedTime] = useState<TimeType>(date[4]);

  useEffect(() => {
    setTimeout(() => {
      setClosedTime(date[5]);
    }, 4000);
  }, []);

  return (
    <>
      <Descriptions
        title="1、overdueTime： 组件内部会自动计算到现在的时间，在大于7天、1-7天，1天内展示不同的UI"
        column={1}
        data={[
          {
            label: '组件内置逻辑',
            value: 'overdueTime只会在displayType设置为normal时生效(内置状态为Normal)',
          },
