          },
          {
            label: '内置状态(1-7天)',
            value: (
              <CFeeType
                chargeStatus="Normal"
                chargeType="PrePaid"
                statusChangeTime={{ overdueTime: date[1], closedTime: closedTime, reclaimTime: date[3] }}
              />
            ),
          },
          {
            label: '自定义map(1天内)',
            value: (
              <CFeeType
                chargeStatus="cancel"
                chargeType="PrePaid"
                customStatusMap={customStatusMap}
