import React, { useState } from 'react';
import { CFeeType, CRadio, Space } from '@cloud-materials/common';
import dayjs from 'dayjs';

enum Status {
  Running = 'Running',
  Closing = 'Closing',
  Closed = 'Closed',
  Deleting = 'Deleting',
  Deleted = 'Deleted',
}

enum ChargeType {
  PrePaid = 'PrePaid',
  PostPaid = 'PostPaid',
}

const StatusLabel: Record<Status, string> = {
  [Status.Running]: '运行中',
  [Status.Closing]: '关停中',
  [Status.Closed]: '已关停',
  [Status.Deleting]: '删除中',
  [Status.Deleted]: '已删除',
};

const ChargeTypeLabel: Record<ChargeType, string> = {
  [ChargeType.PrePaid]: '包年包月',
  [ChargeType.PostPaid]: '按量计费',
};

export default () => {
  const date = [dayjs().add(4, 'd').add(20, 'h').valueOf(), dayjs().add(20, 'h').valueOf()];
  const [status, setStatus] = useState<Status>(Status.Running);
  const [chargeType, setChargeType] = useState<ChargeType>(ChargeType.PostPaid);
  return (
    <Space direction="vertical">
      <h4>
        计费状态统一规范中并未定义关停状态和删除状态，组件支持配置isClosed和isReclaim属性，解决计费方式为【到期/欠费】，但是实际为关停/释放
      </h4>
      <div>
        <span>点击切换实例状态：</span>
        <CRadio.Group
          options={Object.entries(StatusLabel).map(([key, val]) => ({ label: val, value: key }))}
          onChange={setStatus}
          value={status}
        />
      </div>
      <div>
        <span>点击切换计费方式：</span>
        <CRadio.Group
          options={Object.entries(ChargeTypeLabel).map(([key, val]) => ({ label: val, value: key }))}
          onChange={setChargeType}
          value={chargeType}
        />
      </div>
      <CFeeType
        chargeType={chargeType}
        chargeStatus={chargeType === ChargeType.PostPaid ? 'Owing' : 'Overdue'}
        statusChangeTime={{ reclaimTime: date[0], closedTime: date[1] }}
        isClosed={[Status.Closed, Status.Deleting].includes(status)}
        isReclaim={[Status.Deleted].includes(status)}
      />
    </Space>
  );
};

